/** WKS-CONT-LLAVE: moneda + situación inicial + final + CHVV + seguridad lógica + CHECKBOLT + precámara. */
record LlaveContingencia(int moneda, int sitInicial, int sitFinal, int chvv,
                         int seguridadLogica, int causaCheckbolt, int precamara) {
    static LlaveContingencia de(IntentoPago i) {
        return new LlaveContingencia(i.moneda(), i.situacionInicial(), i.situacionFinal(),
                i.codigoChvv(), i.seguridadLogica(), i.causaCheckbolt(), i.codigoPrecamara());
    }
}

record Renglon(LlaveContingencia llave, long cheques, BigDecimal importe) {

    private static final List<String> SITUACIONES = List.of(            // WKS-TABLA-STATUS
            "INEXISTENTE", "LIBERADO", "PROTEGIDO", "CANCELADO", "PREVENIDO",
            "CERTIFICADO", "PROT C/IMPORTE", "REVOCADO", "NO LIBERADO", "PAGADO");

    /** Fuera de 0..9 se imprime el número, igual que WLI-R04-L08-SITININ. */
    static String situacion(int codigo) {
        return (codigo >= 0 && codigo < SITUACIONES.size())
                ? SITUACIONES.get(codigo) : String.valueOf(codigo);
    }
}

/** El archivo llega ordenado por la llave; el corte equivale a agrupar en orden. */
Map<LlaveContingencia, Renglon> resume(Stream<IntentoPago> ordenados) {
    return ordenados.collect(Collectors.groupingBy(LlaveContingencia::de, LinkedHashMap::new,
            Collectors.collectingAndThen(Collectors.toList(), l -> new Renglon(
                    LlaveContingencia.de(l.get(0)), l.size(),
                    l.stream().map(IntentoPago::importe).reduce(BigDecimal.ZERO, BigDecimal::add)))));
}

/** WKS-TABLA-ERRCVV: leyenda por código 1, 2 y 3. */
public enum ErrorChvv {
    SIN_CODIGO_EN_S127("SIN CODIGO CHVV EN S127"),
    SIN_CODIGO_EN_CHEQUE("SIN CODIGO CHVV EN CHEQUE"),
    CODIGOS_DIFERENTES("CODIGOS CHVV DIFERENTES");
    final String leyenda;
    ErrorChvv(String l) { leyenda = l; }
    static ErrorChvv de(int codigo) { return values()[codigo - 1]; }   // solo se invoca con 1..3
}

/** 50013300 / 50013350: solo los intentos con CHVV 1, 2 o 3; corte y total por moneda. */
void detalleChvv(Stream<IntentoPago> porMonedaYChequera, ReporteChvv r05) {
    porMonedaYChequera
        .filter(IntentoPago::conErrorChvv)
        .collect(Collectors.groupingBy(IntentoPago::moneda, TreeMap::new, Collectors.toList()))
        .forEach((moneda, lista) -> {
            r05.encabezado(moneda);
            lista.forEach(i -> r05.renglon(i.sucursalOpera(), i.cajaOpera(), i.nominaOperador(),
                    i.sucursalPromotora(), i.contrato(), i.prefijo(), i.cuenta(),
                    i.numeroCheque(), i.importe(), ErrorChvv.de(i.codigoChvv()).leyenda));
            r05.total(lista.size(), lista.stream().map(IntentoPago::importe)
                    .reduce(BigDecimal.ZERO, BigDecimal::add));
        });
}

/** Leyendas que P125 imprime al pie del reporte 004 (60004120-ESCLIN-SEG). */
public enum SeguridadLogica {
    NIVEL_00("VALIDA CHEQUES PREVENIDOS"),
    NIVEL_01("VALIDA CHEQUES PREVENIDOS Y PAGADOS"),
    NIVEL_02("VALIDA CHEQUES PREVENIDOS, PAGADOS E INEXISTENTES"),
    NIVEL_03("VALIDA CHEQUES PREVENIDOS, PAGADOS, INEXISTENTES Y NO LIBERADOS"),
    NIVEL_04("VALIDA CHEQUES PREVENIDOS E INEXISTENTES");
    final String leyenda;
    SeguridadLogica(String l) { leyenda = l; }
}

public enum CausaCheckbolt {
    INCORRECTO(1), NO_CAPTURADO(2), INEXISTENTE(3), NO_DISPONIBLE(4);
    final int codigo;
    CausaCheckbolt(int c) { codigo = c; }
    static Optional<CausaCheckbolt> de(int c) {          // fuera de 1..4: DESCONOCIDO
        return Arrays.stream(values()).filter(v -> v.codigo == c).findFirst();
    }
}

